def first_and_last(items):
    if not items:
        return []
    return [items[0], items[-1]]

def max_or_none(nums):
    if not nums:
        return None
    return max(nums)

def repeat_string(text, n):
    if n <= 0:
        return ""
    return text * n

def first_index(items, target):
    for i, item in enumerate(items):
        if item == target:
            return i
    return -1

def binary_search(nums, target):
    low, high = 0, len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def is_balanced(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

def run_length_encode(s):
    result = []
    for ch in s:
        if result and result[-1][0] == ch:
            result[-1][1] += 1
        else:
            result.append([ch, 1])
    return "".join(ch + str(count) for ch, count in result)

def caesar_shift(text, k):
    result = []
    for ch in text:
        if "a" <= ch <= "z":
            result.append(chr((ord(ch) - 97 + k) % 26 + 97))
        elif "A" <= ch <= "Z":
            result.append(chr((ord(ch) - 65 + k) % 26 + 65))
        else:
            result.append(ch)
    return "".join(result)

def flatten_deep(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten_deep(item))
        else:
            result.append(item)
    return result

def word_frequencies(text):
    counts = {}
    for word in text.split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def rotate_left(nums, k):
    if not nums:
        return []
    k %= len(nums)
    return nums[k:] + nums[:k]

def longest_word(text):
    words = text.split()
    if not words:
        return None
    return max(words, key=len)

def is_palindrome(s):
    cleaned = [ch.lower() for ch in s if ch.isalnum()]
    return cleaned == cleaned[::-1]

import re


def slugify(text):
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")

def parse_signed_int(s):
    if not s:
        return None
    body = s[1:] if s[0] in "+-" else s
    if not body or not body.isascii() or not body.isdigit():
        return None
    value = int(body)
    return -value if s[0] == "-" else value

def deep_merge(a, b):
    result = dict(a)
    for key, value in b.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = deep_merge(result[key], value)
        else:
            result[key] = value
    return result

def top_k(items, k):
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1
    ordered = sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))
    return ordered[:k] if k > 0 else []

def merge_intervals(intervals):
    merged = []
    for start, end in sorted(intervals):
        if merged and start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

def snake_to_camel(s):
    parts = s.split("_")
    result = parts[0].lower()
    for part in parts[1:]:
        part = part.lower()
        if part:
            result += part[0].upper() + part[1:]
    return result

def dedupe_ci(items):
    seen = set()
    result = []
    for item in items:
        key = item.lower()
        if key not in seen:
            seen.add(key)
            result.append(item)
    return result

def from_roman(s):
    pairs = [("M", 1000), ("CM", 900), ("D", 500), ("CD", 400), ("C", 100),
             ("XC", 90), ("L", 50), ("XL", 40), ("X", 10), ("IX", 9),
             ("V", 5), ("IV", 4), ("I", 1)]
    if not s or any(ch not in "IVXLCDM" for ch in s):
        return None
    total, i = 0, 0
    for symbol, value in pairs:
        while s.startswith(symbol, i):
            total += value
            i += len(symbol)
    if i != len(s) or total > 3999:
        return None
    rest, encoded = total, ""
    for symbol, value in pairs:
        count, rest = divmod(rest, value)
        encoded += symbol * count
    return total if encoded == s else None
